def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_d = op.count('D')

    if n >= 10 and op_d == n:
        return 'D'
    if op_d == 0:
        return 'C'

    last_my, last_op = history[-1]

    if last_op == 'D':
        run = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                run += 1
            else:
                break

        if last_my == 'C' and n >= 2:
            my2, op2 = history[-2]
            if my2 == 'C' and op2 == 'D':
                return 'D'

        if run >= 3:
            return 'C'
        else:
            return 'D'
    else:
        if last_my == 'D':
            return 'D'
        else:
            return 'C'
